use ingetrazo_gui::app::IngeTrazoApp;
use ingetrazo_core::composition::{Sheet,SheetItem};
fn record(app:&IngeTrazoApp,label:&str)->serde_json::Value{let sheet=&app.scene.sheets[0];let history=&app.composer_state.sheet_history[&sheet.id];serde_json::json!({"label":label,"texts":sheet.items.iter().filter_map(|i|if let SheetItem::Text(t)=i{Some(serde_json::json!({"x":t.pos.0,"y":t.pos.1,"text":t.text,"z":sheet.native_items.get(&t.id).and_then(|v|v.get("z")).and_then(|v|v.as_f64()).unwrap_or(0.)}))}else{None}).collect::<Vec<_>>(),"undo":history.0.len(),"redo":history.1.len(),"mode":if app.composer_state.text_tool{"texto"}else{"select"}})}
fn main(){let mut app=IngeTrazoApp::new();app.set_language("en");app.scene.sheets=vec![Sheet::default()];app.scene.sheets[0].items.clear();app.scene.active_sheet_index=Some(0);let mut rows=vec![];let id=app.place_composer_text(0,(23.,41.)).unwrap();rows.push(record(&app,"placed"));let original=app.scene.sheets.clone();app.begin_composer_text_edit(0,id).unwrap();app.composer_state.inline_text.as_mut().unwrap().draft="Hello\nworld\n\n".into();assert_eq!(app.scene.sheets,original);rows.push(record(&app,"draft"));app.finish_composer_text_edit(true).unwrap();rows.push(record(&app,"committed"));let changed=app.scene.sheets.clone();app.undo_composer_edit();assert_eq!(app.scene.sheets,original);rows.push(record(&app,"undo"));app.redo_composer_edit();assert_eq!(app.scene.sheets,changed);rows.push(record(&app,"redo"));app.begin_composer_text_edit(0,id).unwrap();app.composer_state.inline_text.as_mut().unwrap().draft="discard".into();app.finish_composer_text_edit(false).unwrap();assert_eq!(app.scene.sheets,changed);rows.push(record(&app,"cancel"));app.begin_composer_text_edit(0,id).unwrap();app.finish_composer_text_edit(true).unwrap();rows.push(record(&app,"noop"));app.scene.sheets[0].native_items.get_mut(&id).unwrap()["locked"]=serde_json::json!(true);assert!(app.begin_composer_text_edit(0,id).is_err());rows.push(record(&app,"locked"));assert!(app.place_composer_text(0,(f64::NAN,0.)).is_err());println!("{}",serde_json::json!({"rows":rows}));}
